 C[m]+=1;J.append(dict(id='E9-'+m[2:4]+m[-2:]+f'-{C[m]:03}',date=m+f'-{day:02}' if day and not slug else m+f'-{calendar.monthrange(int(m[:4]),int(m[-2:]))[1]}',date_precision='day' if day and not slug else 'month',subject=sub,block=block,title=title,why=why+(' Magazine coverage month is an editorial index, not necessarily the event date.' if slug else ''),facts=facts.split('|'),static_link=static,analysis=analysis.split('|'),trap=trap,mains=mains,ap=ap,priority=p,sources=keys,status='Historical snapshot; later law, rules, implementation and statistics need separately dated checks',checked='2026-11-07',evidence_access='Actual access scope in source registry; static links, analysis and exam guidance are original',**extra))
